describe('WovenDialogueShell composition', () => {
  afterEach(() => { vi.unstubAllGlobals(); });
  beforeEach(() => {
    shellState.pathname = '/';
    shellState.query = '';
    shellState.projectRoot = '/repo/projects/chirality-app-dev';
    shellState.streaming = false;
  });

  it.each(['dialogue', 'workbench', 'pipeline'] as const)('only mounts Dialogue even with historical %s surface input', (surface) => {
    const html = renderToStaticMarkup(<WovenDialogueShell defaultSurface={surface} />);
    expect(navigatorItemCount(html)).toBe(1);
    expect(html).toContain('<span>Dialogue</span>');
    expect(html).toContain('data-woven-surface="dialogue"');
    expect(html).toContain('data-chat-panel="mounted"');
    expect(html).not.toContain('data-focused-surface');
    expect(html).not.toContain('data-workbench-surface');
    expect(html).not.toContain('data-pipeline-surface');
    expect(html).not.toContain('woven-navigator-chevron');
    expect(html).not.toContain('hidden=');
  });

  it('preserves controller identity and focusable composer through replay, panel controls, resize, and return', async () => {
    const focus = vi.fn();
    const persist = vi.fn();
    vi.stubGlobal('window', { localStorage: { getItem: () => JSON.stringify({ schema: 'chirality.woven-workspace/v1', coordinationView: 'work', sessionSurfaces: { recorded: 'workbench' } }), setItem: persist }, addEventListener: vi.fn(), removeEventListener: vi.fn(), requestAnimationFrame: (callback: () => void) => callback() });
    vi.stubGlobal('document', { querySelector: () => ({ focus }) });
    shellState.mounted = 0; shellState.unmounted = 0; shellState.replayLoad.mockClear();
    let tree!: ReactTestRenderer;
    await act(async () => { tree = create(<WovenDialogueShell defaultSurface="dialogue" />); });
    expect(tree.root.findByType(CoordinationPanel).props.activeView).toBe('agents');
    expect(tree.root.findByType(Navigator).props.sessionSurfaces).toEqual({ recorded: 'workbench', primary: 'dialogue' });
    expect(JSON.parse(persist.mock.calls.at(-1)![1]).sessionSurfaces).toEqual({ recorded: 'workbench', primary: 'dialogue' });
    const input = tree.root.findByProps({ 'data-chat-input': 'primary' });
    const assertPrimary = () => {
      expect(tree.root.findByProps({ 'data-chat-input': 'primary' })).toBe(input);
      let node: typeof input | null = input;
      while (node) { expect(node.props.hidden).not.toBe(true); expect(node.props['aria-hidden']).not.toBe(true); node = node.parent; }
      expect(input.props.disabled).toBeUndefined();
      expect(shellState.mounted).toBe(1); expect(shellState.unmounted).toBe(0);
      expect(tree.root.findAll(node => Boolean(node.props['data-focused-surface']))).toHaveLength(0);
    };
    const click = (label: string) => act(() => { tree.root.findAllByType('button').find(button => button.children.join('') === label)!.props.onClick(); });
    click('Close Coordination');
    act(() => tree.root.findByType(Navigator).props.onSelectSession('recorded'));
    expect(tree.root.findByType(CoordinationPanel).props.activeView).toBe('session');
    expect(tree.root.findByProps({ 'data-replay-lens': 'LOADING' })).toBeTruthy();
    assertPrimary();
    act(() => shellState.replayNotify?.({ status: 'UNAVAILABLE', selectedSessionId: 'recorded', message: 'offline' }));
    assertPrimary();
    click('Retry');
    expect(shellState.replayLoad).toHaveBeenCalledTimes(2);
    act(() => shellState.replayNotify?.({ status: 'READY', projection: { selectedSessionId: 'recorded' } }));
    assertPrimary();
    click('Agents'); assertPrimary();
    act(() => tree.root.findByType(Navigator).props.onSelectSession('recorded'));
    expect(tree.root.findByType(CoordinationPanel).props.activeView).toBe('session');
    expect(shellState.replayLoad).toHaveBeenCalledTimes(2); assertPrimary();
    click('Agents'); click('Session'); assertPrimary();
    for (const region of ['Navigator', 'Coordination']) { click(`Close ${region}`); assertPrimary(); click(`Open ${region}`); assertPrimary(); }
    for (const label of ['Resize Navigator', 'Resize Coordination Panel', 'Resize Activity Shelf']) {
      for (const key of ['Home', 'End', 'ArrowLeft']) {
        act(() => tree.root.findByProps({ 'aria-label': label }).props.onKeyDown({ key, shiftKey: false, preventDefault: vi.fn() }));
        assertPrimary();
      }
    }
    click('Return to primary dialogue');
    expect(focus).toHaveBeenCalled(); assertPrimary();
    expect(tree.root.findAll(node => Boolean(node.props['data-replay-lens']))).toHaveLength(0);
    shellState.streaming = true;
    act(() => tree.update(<WovenDialogueShell defaultSurface="dialogue" />));
    act(() => tree.root.findByType(Navigator).props.onSelectSession('recorded'));
    expect(shellState.replayLoad).toHaveBeenCalledTimes(2); assertPrimary();
    act(() => tree.unmount());
    expect(shellState.unmounted).toBe(1);
  });

  it('preserves the legacy compatibility link with the current query string', () => {
    shellState.pathname = '/workbench';
    shellState.query = 'agent=CHANGE';

    const html = renderToStaticMarkup(<WovenDialogueShell defaultSurface="workbench" />);

    expect(html).toContain('href="/workbench?agent=CHANGE&amp;legacy=1"');
  });
});

'use client';

import { useEffect, useMemo, useState } from 'react';
import { resolveDocumentViewState } from '../../lib/shell/document-view-state';
import { useWorkspace } from '../workspace/workspace-provider';
import { ChatMarkdown } from './chat-markdown';

type Deliverable = {
  id: string;
  name: string;
  pkg: string;
  status: string;
  path: string;
};

type DeliverablesResponse = {
  deliverables?: Deliverable[];
  deliverableContracts?: Array<{
    path: string;
    selectedProductionDocuments: Array<{ fileName: string }>;
  }>;
  error?: { message?: string };
};

type ContentResponse = {
  content?: string;
  file?: string;
  error?: { message?: string };
};

// The well-known deliverable document files (see the knowledge buckets in
// `lib/workspace/filesystem.ts`). `_STATUS.md` is always present; the rest are
// offered so the viewer can open whichever the deliverable contains. A missing
// file simply surfaces the endpoint's 404.
const CONTROL_PLANE_DOCUMENT_FILES = [
  '_STATUS.md',
  '_CONTEXT.md',
  '_REFERENCES.md',
  '_DEPENDENCIES.md',
  '_SEMANTIC.md',
  'MEMORY.md'
];

const DEFAULT_FILE = '_STATUS.md';

export function DocumentView(): JSX.Element {
  const { projectRoot } = useWorkspace();
  const [deliverables, setDeliverables] = useState<Deliverable[]>([]);
  const [canonicalDocumentsByPath, setCanonicalDocumentsByPath] = useState<
    Record<string, string[]>
  >({});
  const [rosterLoading, setRosterLoading] = useState(false);
  const [rosterError, setRosterError] = useState<string | null>(null);
  const [selectedPath, setSelectedPath] = useState<string>('');
  const [selectedFile, setSelectedFile] = useState<string>(DEFAULT_FILE);

  const [content, setContent] = useState<string | null>(null);
  const [contentLoading, setContentLoading] = useState(false);
  const [contentError, setContentError] = useState<string | null>(null);

  // Load the deliverable roster whenever the Working Root changes.
  useEffect(() => {
    let cancelled = false;
    setDeliverables([]);
    setCanonicalDocumentsByPath({});
    setRosterError(null);
    setSelectedPath('');
    setContent(null);
    setContentError(null);

    if (!projectRoot) {
      setRosterLoading(false);
      return () => {
        cancelled = true;
      };
    }

    setRosterLoading(true);

    async function loadRoster(): Promise<void> {
      try {
        const response = await fetch(
          `/api/project/deliverables?projectRoot=${encodeURIComponent(projectRoot as string)}`
        );
        const payload = (await response.json()) as DeliverablesResponse;
        if (cancelled) {
          return;
        }
        if (!response.ok || !payload.deliverables) {
          throw new Error(payload.error?.message ?? 'Unable to load deliverables.');
        }
        setDeliverables(payload.deliverables);
        setCanonicalDocumentsByPath(
          Object.fromEntries(
            (payload.deliverableContracts ?? []).map((contract) => [
              contract.path,
              contract.selectedProductionDocuments.map((file) => file.fileName)
            ])
          )
        );
        setSelectedPath(payload.deliverables[0]?.path ?? '');
      } catch (error) {
        if (cancelled) {
          return;
        }
        setRosterError(error instanceof Error ? error.message : 'Unable to load deliverables.');
      } finally {
        if (!cancelled) {
          setRosterLoading(false);
        }
      }
    }

    void loadRoster();
    return () => {
      cancelled = true;
    };
  }, [projectRoot]);

  // Fetch the selected document content.
  useEffect(() => {
    let cancelled = false;
    if (!projectRoot || !selectedPath) {
      setContent(null);
      setContentError(null);
      setContentLoading(false);
      return () => {
        cancelled = true;
      };
    }

    async function loadContent(): Promise<void> {
      setContentLoading(true);
      setContentError(null);
      try {
        const response = await fetch(
          `/api/working-root/deliverable/content?projectRoot=${encodeURIComponent(
            projectRoot as string
          )}&deliverablePath=${encodeURIComponent(selectedPath)}&file=${encodeURIComponent(
            selectedFile
          )}`
        );
        const payload = (await response.json()) as ContentResponse;
        if (cancelled) {
          return;
        }
        if (!response.ok || typeof payload.content !== 'string') {
          throw new Error(payload.error?.message ?? 'Unable to load document.');
        }
        setContent(payload.content);
      } catch (error) {
        if (cancelled) {
          return;
        }
        setContent(null);
        setContentError(error instanceof Error ? error.message : 'Unable to load document.');
      } finally {
        if (!cancelled) {
          setContentLoading(false);
        }
      }
    }

    void loadContent();
    return () => {
      cancelled = true;
    };
  }, [projectRoot, selectedPath, selectedFile]);

  const documentFiles = useMemo(
    () => [
      CONTROL_PLANE_DOCUMENT_FILES[0],
      ...(canonicalDocumentsByPath[selectedPath] ?? []),
      ...CONTROL_PLANE_DOCUMENT_FILES.slice(1)
    ],
    [canonicalDocumentsByPath, selectedPath]
  );

  const body = useMemo(() => {
    const state = resolveDocumentViewState({
      hasProjectRoot: Boolean(projectRoot),
      rosterLoading,
      rosterError,
      deliverableCount: deliverables.length,
      contentLoading,
      contentError,
      hasContent: content !== null
    });

    switch (state.kind) {
      case 'no-root':
        return <p className="panel-empty">Select a Working Root to view deliverable documents.</p>;
      case 'roster-loading':
        return <p className="panel-empty">Loading deliverables...</p>;
      case 'roster-error':
        return <p className="panel-error">{state.message}</p>;
      case 'empty':
        return <p className="panel-empty">No deliverables found in this Working Root.</p>;
      case 'content-loading':
        return <p className="panel-empty">Loading document...</p>;
      case 'content-error':
        return <p className="panel-error">{state.message}</p>;
      case 'content':
        return <ChatMarkdown source={content as string} />;
      case 'idle':
      default:
        return <p className="panel-empty">Select a deliverable and document to preview.</p>;
    }
  }, [projectRoot, rosterLoading, rosterError, deliverables, contentLoading, contentError, content]);

  return (
    <aside className="panel panel--document">
      <header className="panel-header">
        <h2>Document</h2>
        {deliverables.length > 0 ? (
          <div className="document-view-controls">
            <label className="document-view-selector">
              <span>Deliverable</span>
              <select
                value={selectedPath}
                onChange={(event) => {
                  setSelectedPath(event.target.value);
                  setSelectedFile(DEFAULT_FILE);
                }}
              >
                {deliverables.map((deliverable) => (
                  <option key={deliverable.path} value={deliverable.path}>
                    {deliverable.id} — {deliverable.name}
                  </option>
                ))}
              </select>
            </label>
            <label className="document-view-selector">
              <span>File</span>
              <select
                value={selectedFile}
                onChange={(event) => {
                  setSelectedFile(event.target.value);
                }}
              >
                {documentFiles.map((file) => (
                  <option key={file} value={file}>
                    {file}
                  </option>
                ))}
              </select>
            </label>
          </div>
        ) : null}
      </header>
      <div className="panel-body document-view-body">{body}</div>
    </aside>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  FILE_TREE_POLL_INTERVAL_MS,
  createRefreshScheduler,
  shouldPollWhenHidden,
  shouldRefreshForVisibilityState
} from '../../lib/workspace/file-tree-refresh';
import { useWorkspace } from '../workspace/workspace-provider';

const TREE_DEPTH = 3;

type TreeNode = {
  name: string;
  path: string;
  kind: 'directory' | 'file' | 'symlink';
  children?: TreeNode[];
  truncated?: boolean;
};

type TreeResponse = {
  root: TreeNode;
  depth: number;
  scannedAt: string;
};

type TreeNodeViewProps = {
  node: TreeNode;
  expandedByPath: Record<string, boolean>;
  onToggle: (nodePath: string) => void;
};

function TreeNodeView({ node, expandedByPath, onToggle }: TreeNodeViewProps): JSX.Element {
  const hasChildren = node.kind === 'directory' && Boolean(node.children?.length);
  const isExpanded = hasChildren ? (expandedByPath[node.path] ?? true) : true;
  const icon = node.kind === 'directory' ? 'DIR' : node.kind === 'symlink' ? 'LNK' : 'FILE';

  return (
    <li>
      <div className={`tree-item tree-item--${node.kind}`}>
        {hasChildren ? (
          <button
            type="button"
            className="tree-toggle"
            aria-label={isExpanded ? `Collapse ${node.name}` : `Expand ${node.name}`}
            onClick={() => {
              onToggle(node.path);
            }}
          >
            {isExpanded ? '-' : '+'}
          </button>
        ) : (
          <span className="tree-toggle tree-toggle--spacer" aria-hidden="true">
            {' '}
          </span>
        )}
        <span className="tree-item-icon">{icon}</span>
        <span className="tree-item-name" title={node.path}>
          {node.name}
        </span>
      </div>
      {hasChildren && isExpanded ? (
        <ul className="tree-list">
          {node.children?.map((child) => (
            <TreeNodeView
              key={child.path}
              node={child}
              expandedByPath={expandedByPath}
              onToggle={onToggle}
            />
          ))}
        </ul>
      ) : null}
      {node.truncated ? (
        <div className="tree-truncated">Directory listing truncated for responsiveness.</div>
      ) : null}
    </li>
  );
}

export function FileTreePanel(): JSX.Element {
  const { projectRoot } = useWorkspace();
  const [tree, setTree] = useState<TreeNode | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [expandedByPath, setExpandedByPath] = useState<Record<string, boolean>>({});
  const [refreshNonce, setRefreshNonce] = useState(0);
  const [pollingGeneration, setPollingGeneration] = useState(0);
  const latestRequestIdRef = useRef(0);
  const treeRef = useRef<TreeNode | null>(null);

  useEffect(() => {
    treeRef.current = tree;
  }, [tree]);

  useEffect(() => {
    setExpandedByPath({});
    setTree(null);
    treeRef.current = null;
    setError(null);
    setLoading(false);
  }, [projectRoot]);

  const triggerRefresh = useCallback(() => {
    setRefreshNonce((current) => current + 1);
  }, []);

  const restartPolling = useCallback(() => {
    setPollingGeneration((current) => current + 1);
  }, []);

  useEffect(() => {
    let cancelled = false;

    async function loadTree(): Promise<void> {
      if (!projectRoot) {
        setTree(null);
        setError(null);
        return;
      }

      const requestId = latestRequestIdRef.current + 1;
      latestRequestIdRef.current = requestId;
      const showInitialLoading = treeRef.current === null;
      if (showInitialLoading) {
        setLoading(true);
      }

      try {
        const response = await fetch(
          `/api/working-root/tree?projectRoot=${encodeURIComponent(projectRoot)}&depth=${TREE_DEPTH}`
        );
        const payload = (await response.json()) as TreeResponse & {
          error?: { message?: string };
        };

        if (!response.ok || !payload.root) {
          throw new Error(payload.error?.message ?? 'Unable to load directory tree');
        }

        if (cancelled || requestId !== latestRequestIdRef.current) {
          return;
        }

        setTree(payload.root);
        setError(null);
      } catch (loadError) {
        if (cancelled || requestId !== latestRequestIdRef.current) {
          return;
        }

        const message = loadError instanceof Error ? loadError.message : 'Unable to load directory tree';
        setError(message);
        setTree(null);
      } finally {
        if (!cancelled && requestId === latestRequestIdRef.current && showInitialLoading) {
          setLoading(false);
        }
      }
    }

    void loadTree();

    return () => {
      cancelled = true;
    };
  }, [projectRoot, refreshNonce]);

  useEffect(() => {
    if (!projectRoot) {
      return;
    }

    const intervalId = window.setInterval(() => {
      const hidden = document.visibilityState === 'hidden';
      if (!shouldPollWhenHidden(hidden)) {
        return;
      }

      triggerRefresh();
    }, FILE_TREE_POLL_INTERVAL_MS);

    return () => {
      window.clearInterval(intervalId);
    };
  }, [projectRoot, pollingGeneration, triggerRefresh]);

  useEffect(() => {
    if (!projectRoot) {
      return;
    }

    const scheduler = createRefreshScheduler({
      onRefresh: triggerRefresh,
      onAfterRefresh: restartPolling
    });

    const onVisibilityChange = (): void => {
      if (shouldRefreshForVisibilityState(document.visibilityState)) {
        scheduler.schedule();
      }
    };

    const onWindowFocus = (): void => {
      scheduler.schedule();
    };

    document.addEventListener('visibilitychange', onVisibilityChange);
    window.addEventListener('focus', onWindowFocus);

    return () => {
      scheduler.cancel();
      document.removeEventListener('visibilitychange', onVisibilityChange);
      window.removeEventListener('focus', onWindowFocus);
    };
  }, [projectRoot, restartPolling, triggerRefresh]);

  const toggleExpanded = useCallback((nodePath: string): void => {
    setExpandedByPath((current) => ({
      ...current,
      [nodePath]: !(current[nodePath] ?? true)
    }));
  }, []);

  const panelBody = useMemo(() => {
    if (!projectRoot) {
      return <p className="panel-empty">Select a Working Root to view filesystem contents.</p>;
    }

    if (loading) {
      return <p className="panel-empty">Loading directory tree...</p>;
    }

    if (error) {
      return <p className="panel-error">{error}</p>;
    }

    if (!tree) {
      return <p className="panel-empty">No files available for this root.</p>;
    }

    return (
      <ul className="tree-list">
        <TreeNodeView node={tree} expandedByPath={expandedByPath} onToggle={toggleExpanded} />
      </ul>
    );
  }, [projectRoot, loading, error, tree, expandedByPath, toggleExpanded]);

  return (
    <aside className="panel panel--file-tree">
      <header className="panel-header">
        <h2>File Tree</h2>
      </header>
      <div className="panel-body">{panelBody}</div>
    </aside>
  );
}

'use client';

