function DiagnosticList({
  diagnostics
}: {
  diagnostics: readonly ProjectionDiagnostic[];
}): JSX.Element | null {
  if (diagnostics.length === 0) {
    return null;
  }

  return (
    <ul className="woven-replay-diagnostics" aria-label="Replay disclosures">
      {diagnostics.map((diagnostic, index) => (
        <li key={`${diagnostic.code}:${index}`}>
          <strong>{diagnostic.code}</strong>: {diagnostic.message}
        </li>
      ))}
    </ul>
  );
}

function TranscriptItemView({ item }: { item: TranscriptItem }): JSX.Element {
  const artifactReference =
    item.artifact?.artifactRelativePath ?? item.artifact?.artifactPath;

  return (
    <li className="woven-replay-item">
      <div>
        <strong>{item.title}</strong>
        <span> — {item.status}</span>
      </div>
      {item.text ? <p>{item.text}</p> : null}
      {item.summary ? <p>{item.summary}</p> : null}
      {artifactReference ? (
        <p>
          <span>Artifact reference: </span>
          <code>{artifactReference}</code>
        </p>
      ) : null}
      <p>
        <span>Event: </span>
        <code>{item.eventId}</code>
        <span> / {item.eventType}</span>
      </p>
    </li>
  );
}

function ReadyReplay({
  projection
}: {
  projection: SelectedSessionReplayProjection;
}): JSX.Element {
  const attribution = projection.session;

  return (
    <>
      <section
        className="woven-replay-provenance"
        aria-label="Replay provenance and status"
        // The Session panel is narrower than the former full-width replay.
        // Stack both the groups and their label/value tracks so values retain
        // the panel's available width, including long canonical source paths.
        style={{ gridTemplateColumns: 'minmax(0, 1fr)' }}
      >
        <dl style={{ gridTemplateColumns: 'minmax(0, 1fr)' }}>
          <dt>Source</dt>
          <dd>
            <code>{projection.sourceReference}</code>
          </dd>
          <dt>Observed</dt>
          <dd>{projection.observedAt}</dd>
          <dt>Disclosure</dt>
          <dd>{projection.disclosure}</dd>
          <dt>Currency</dt>
          <dd>{projection.currency}</dd>
          <dt>Events</dt>
          <dd>{projection.sourceEventCount}</dd>
          <dt>Transcript items shown</dt>
          <dd>
            {projection.bounded
              ? `${projection.bounded.rendered} of ${projection.bounded.available}`
              : projection.renderedItemCount}
          </dd>
          <dt>Malformed records skipped</dt>
          <dd>{projection.malformedLineCount}</dd>
        </dl>
        {attribution ? (
          <dl
            aria-label="Recorded session attribution"
            style={{ gridTemplateColumns: 'minmax(0, 1fr)' }}
          >
            {attribution.persona ? (
              <>
                <dt>Persona</dt>
                <dd>{attribution.persona}</dd>
              </>
            ) : null}
            {attribution.role ? (
              <>
                <dt>Role</dt>
                <dd>{attribution.role}</dd>
              </>
            ) : null}
            {attribution.runtimeStatus ? (
              <>
                <dt>Recorded runtime status</dt>
                <dd>{attribution.runtimeStatus}</dd>
              </>
            ) : null}
            {attribution.adapterId ? (
              <>
                <dt>Adapter</dt>
                <dd>{attribution.adapterId}</dd>
              </>
            ) : null}
            {attribution.providerId ? (
              <>
                <dt>Provider</dt>
                <dd>{attribution.providerId}</dd>
              </>
            ) : null}
            {attribution.model ? (
              <>
                <dt>Recorded model selection</dt>
                <dd>{attribution.model}</dd>
              </>
            ) : null}
            {attribution.residencyEpoch ? (
              <>
                <dt>Residency epoch</dt>
                <dd>{attribution.residencyEpoch}</dd>
              </>
            ) : null}
          </dl>
        ) : (
          <p>Session metadata unavailable; event evidence only.</p>
        )}
      </section>

      <DiagnosticList diagnostics={projection.diagnostics} />

      <section className="woven-replay-transcript" aria-label="Read-only transcript">
        {projection.transcript.items.length === 0 ? (
          <p>
            {projection.disclosure === 'EVIDENCE_ONLY'
              ? 'No transcript items were recorded; canonical event evidence may still exist.'
              : 'No transcript items were recorded for this session.'}
          </p>
        ) : (
          <ol>
            {projection.transcript.items.map((item) => (
              <TranscriptItemView key={item.key} item={item} />
            ))}
          </ol>
        )}
      </section>
    </>
  );
}

/**
 * Observational presentation only. The component intentionally exposes no
 * send, continue, interrupt, permission, resume, boot, delete, or lifecycle
 * action.
 */
export function SelectedSessionReplayLens({
  state,
  primarySessionId,
  onReturnToPrimary,
  onRetry
}: SelectedSessionReplayLensProps): JSX.Element | null {
  if (state.status === 'IDLE') {
    return null;
  }

  const selectedSessionId =
    state.status === 'READY'
      ? state.projection.selectedSessionId
      : state.selectedSessionId;

  return (
    <section
      className="woven-replay-lens"
      style={{ overflowWrap: 'anywhere' }}
      aria-label="Selected-session read-only replay"
      data-replay-state={state.status}
      data-replay-disclosure={
        state.status === 'READY' ? state.projection.disclosure : undefined
      }
    >
      <ReplayHeader
        selectedSessionId={selectedSessionId}
        primarySessionId={primarySessionId}
        onReturnToPrimary={onReturnToPrimary}
      />

      {state.status === 'LOADING' ? (
        <p role="status">Loading canonical replay evidence…</p>
      ) : null}

      {state.status === 'UNAVAILABLE' ? (
        <div role="alert">
          <p>Replay unavailable: {state.message}</p>
          {onRetry ? (
            <button type="button" onClick={onRetry}>
              Retry
            </button>
          ) : null}
        </div>
      ) : null}

      {state.status === 'READY' ? (
        <ReadyReplay projection={state.projection} />
      ) : null}
    </section>
  );
}

'use client';

import { usePathname, useSearchParams } from 'next/navigation';
import {
  default as React,
  Suspense,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent
} from 'react';
import type { SessionRecord } from '@chirality/runtime-contracts/types';
import { listHarnessSessions, harnessApiErrorMessage } from '../../lib/harness/client';
import type { SelectedSessionReplayState } from '../../lib/woven-dialogue/contracts';
import { buildRecordedAgentHierarchy } from '../../lib/woven-dialogue/recorded-agent-hierarchy';
import { guardRecordedSessionSelection } from '../../lib/woven-dialogue/guarded-session-selection';
import {
  createSelectedSessionReplayLoader,
  type SelectedSessionReplayLoader
} from '../../lib/woven-dialogue/selected-session-replay';
import {
  clearProjectScopedWovenWorkspaceState,
  createDefaultWovenWorkspaceState,
  readWovenWorkspaceStateFromStorage,
  recordWovenSessionSurface,
  writeWovenWorkspaceStateToStorage,
  type WovenWorkspaceState
} from '../../lib/woven-dialogue/woven-workspace-state';
import { useHarnessStreaming } from '../workspace/harness-events-provider';
import { useWorkspace } from '../workspace/workspace-provider';
import { ChatPanel } from '../shell/chat-panel';
import { PersonaPicker } from '../shell/persona-picker';
import { useRuntimeEpoch } from '../shell/runtime-connectivity-provider';
import { ShellFrame } from '../shell/shell-frame';
import { ActivityShelf } from './activity-shelf';
import { CoordinationPanel } from './coordination-panel';
import { DialogueViewport } from './dialogue-viewport';
import { Navigator, type WovenSurface } from './navigator';
import { SelectedSessionReplayLens } from './selected-session-replay-lens';

type WovenDialogueShellProps = {
  defaultSurface: WovenSurface;
};

type ResizeTarget = 'navigator' | 'coordination' | 'activity';

function selectedReplayId(state: SelectedSessionReplayState): string | undefined {
  if (state.status === 'READY') {
    return state.projection.selectedSessionId;
  }
  if (state.status === 'LOADING' || state.status === 'UNAVAILABLE') {
    return state.selectedSessionId;
  }
  return undefined;
}

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.max(minimum, Math.min(maximum, value));
}

export function WovenDialogueShell(_props: WovenDialogueShellProps): JSX.Element {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const { projectRoot } = useWorkspace();
  const streaming = useHarnessStreaming();
  const runtimeEpoch = useRuntimeEpoch();
  const [primarySessionId, setPrimarySessionId] = useState<string>();
  const [workspaceState, setWorkspaceState] = useState<WovenWorkspaceState>(
    createDefaultWovenWorkspaceState
  );
  const [coordinationView, setCoordinationView] = useState<'session' | 'agents'>('agents');
  const [stateHydrated, setStateHydrated] = useState(false);
  const [sessions, setSessions] = useState<SessionRecord[]>([]);
  const [sessionsLoading, setSessionsLoading] = useState(false);
  const [sessionsError, setSessionsError] = useState<string | null>(null);
  const [sessionRefreshToken, setSessionRefreshToken] = useState(0);
  const replayLoaderRef = useRef<SelectedSessionReplayLoader>();
  const previousProjectRootRef = useRef(projectRoot);
  const [replayState, setReplayState] = useState<SelectedSessionReplayState>({
    status: 'IDLE'
  });
  const dialogueInputRef = useRef<HTMLInputElement | null>(null);
  const resizeRef = useRef<{
    target: ResizeTarget;
    startX: number;
    startY: number;
    startValue: number;
  } | null>(null);

  if (!replayLoaderRef.current) {
    replayLoaderRef.current = createSelectedSessionReplayLoader();
  }

  useEffect(() => {
    const loader = replayLoaderRef.current as SelectedSessionReplayLoader;
    const unsubscribe = loader.subscribe(setReplayState);
    return () => {
      unsubscribe();
      loader.dispose();
    };
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }
    const stored = readWovenWorkspaceStateFromStorage(window.localStorage);
    setWorkspaceState(stored);
    // Retired Work preferences fall back to the recorded Agents projection.
    setCoordinationView('agents');
    setStateHydrated(true);
  }, []);

  useEffect(() => {
    if (!stateHydrated || typeof window === 'undefined') {
      return;
    }
    writeWovenWorkspaceStateToStorage(window.localStorage, workspaceState);
  }, [stateHydrated, workspaceState]);

  // The recorded session list carries no surface field, so the shell tags the
  // dialogue surface when a session is first observed. Local
  // annotation only (no project truth); first attribution wins, so this is a
  // no-op — same state reference — for every session already tagged.
  useEffect(() => {
    if (!stateHydrated || !primarySessionId) {
      return;
    }
    setWorkspaceState((current) =>
      recordWovenSessionSurface(current, primarySessionId, 'dialogue')
    );
  }, [primarySessionId, stateHydrated]);

  useEffect(() => {
    replayLoaderRef.current?.cancel();
    setSessions([]);
    setSessionsError(null);
    if (
      previousProjectRootRef.current &&
      previousProjectRootRef.current !== projectRoot
    ) {
      setWorkspaceState(clearProjectScopedWovenWorkspaceState);
    }
    previousProjectRootRef.current = projectRoot;
  }, [projectRoot]);

  useEffect(() => {
    if (primarySessionId) {
      setSessionRefreshToken((token) => token + 1);
    }
  }, [primarySessionId, streaming]);

  useEffect(() => {
    if (!projectRoot) {
      setSessions([]);
      setSessionsLoading(false);
      return;
    }

    let cancelled = false;
    setSessionsLoading(true);
    setSessionsError(null);
    listHarnessSessions(projectRoot)
      .then((records) => {
        if (!cancelled) {
          setSessions(records);
        }
      })
      .catch((error) => {
        if (!cancelled) {
          setSessionsError(harnessApiErrorMessage(error));
        }
      })
      .finally(() => {
        if (!cancelled) {
          setSessionsLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
    // `runtimeEpoch` re-lists after a reconnect. The Navigator's flat list and
    // the Coordination panel's hierarchy are both projections of `sessions`, so
    // one re-list repairs all three surfaces at once.
  }, [projectRoot, sessionRefreshToken, runtimeEpoch]);

  // Read at reconnect time only, so the recovery effect below can depend on the
  // epoch alone: depending on the replay state itself would re-arm the effect
  // with every load it performs.
  const replayStateRef = useRef(replayState);
  replayStateRef.current = replayState;
  const sessionsRef = useRef(sessions);
  sessionsRef.current = sessions;

  // A replay lens left showing UNAVAILABLE is the same stale-error class as the
  // panes above, and it is still on screen — the lens is only hidden when the
  // state is IDLE. Reload it once, straight through the loader: the selection
  // guard is for operator clicks, and it answers UNCHANGED for a re-request of
  // the session already selected.
  useEffect(() => {
    if (runtimeEpoch === 0) {
      return;
    }
    const current = replayStateRef.current;
    if (current.status !== 'UNAVAILABLE') {
      return;
    }
    void replayLoaderRef.current?.load(current.selectedSessionId, {
      observedAt: new Date().toISOString(),
      availableSessionIds: new Set(
        sessionsRef.current.map((session) => session.sessionId)
      )
    });
  }, [runtimeEpoch]);

  const hierarchy = useMemo(() => {
    const observedAt = new Date().toISOString();
    return buildRecordedAgentHierarchy(
      sessions.map((session) => {
        const source = session as SessionRecord & Record<string, unknown>;
        return {
          ...source,
          sourceReference: `session:${session.sessionId}`,
          observedAt,
          currency: 'UNKNOWN',
          status: source.status,
          role: source.role
        };
      })
    );
  }, [sessions]);

  const legacyHref = useMemo(() => {
    const params = new URLSearchParams(searchParams.toString());
    params.set('legacy', '1');
    return `${pathname}?${params.toString()}`;
  }, [pathname, searchParams]);

  const updateWorkspaceState = useCallback(
    (patch: Partial<WovenWorkspaceState>): void => {
      setWorkspaceState((current) => ({ ...current, ...patch }));
    },
    []
  );

  const returnToPrimaryDialogue = useCallback((): void => {
    replayLoaderRef.current?.cancel();
    updateWorkspaceState({ selectedReplaySessionId: null });
    window.requestAnimationFrame(() => {
      const input = document.querySelector<HTMLInputElement>('[data-chat-input="primary"]');
      dialogueInputRef.current = input;
      input?.focus();
    });
  }, [updateWorkspaceState]);

  const loadReplay = useCallback(
    (sessionId: string): void => {
      const decision = guardRecordedSessionSelection({
        currentState: replayState,
        requestedSessionId: sessionId,
        primarySessionId,
        recordedSessionIds: sessions.map((session) => session.sessionId),
        liveTurnActive: streaming,
        replayIsolationAvailable: true
      });
      if (decision.outcome === 'RETURN_TO_PRIMARY') {
        returnToPrimaryDialogue();
        return;
      }
      if (decision.outcome === 'UNCHANGED') {
        updateWorkspaceState({ coordinationCollapsed: false });
        setCoordinationView('session');
        return;
      }
      if (decision.outcome !== 'SELECT_REPLAY') {
        return;
      }

      updateWorkspaceState({
        selectedReplaySessionId: sessionId,
        coordinationCollapsed: false
      });
      setCoordinationView('session');
      void replayLoaderRef.current?.load(sessionId, {
        observedAt: new Date().toISOString(),
        availableSessionIds: new Set(sessions.map((session) => session.sessionId))
      });
    },
    [
      primarySessionId,
      replayState,
      returnToPrimaryDialogue,
      sessions,
      streaming,
      updateWorkspaceState
    ]
  );

  const beginResize = useCallback(
    (event: PointerEvent<HTMLDivElement>, target: ResizeTarget): void => {
      if (event.button !== 0) {
        return;
      }
      event.preventDefault();
      const startValue =
        target === 'navigator'
          ? workspaceState.navigatorWidth
          : target === 'coordination'
            ? workspaceState.coordinationWidth
            : workspaceState.activityHeight;
      resizeRef.current = {
        target,
        startX: event.clientX,
        startY: event.clientY,
        startValue
      };
    },
    [workspaceState]
  );

  useEffect(() => {
    const handleMove = (event: globalThis.PointerEvent): void => {
      const resize = resizeRef.current;
      if (!resize) {
        return;
      }
      if (resize.target === 'navigator') {
        updateWorkspaceState({
          navigatorWidth: clamp(resize.startValue + event.clientX - resize.startX, 220, 620),
          navigatorCollapsed: false
        });
      } else if (resize.target === 'coordination') {
        updateWorkspaceState({
          coordinationWidth: clamp(resize.startValue - event.clientX + resize.startX, 280, 680),
          coordinationCollapsed: false
        });
      } else {
        updateWorkspaceState({
          activityHeight: clamp(resize.startValue - event.clientY + resize.startY, 120, 480),
          activityCollapsed: false
        });
      }
    };
    const handleUp = (): void => {
      resizeRef.current = null;
    };
    window.addEventListener('pointermove', handleMove);
    window.addEventListener('pointerup', handleUp);
    window.addEventListener('pointercancel', handleUp);
    return () => {
      window.removeEventListener('pointermove', handleMove);
      window.removeEventListener('pointerup', handleUp);
      window.removeEventListener('pointercancel', handleUp);
    };
  }, [updateWorkspaceState]);

  const resizeByKeyboard = useCallback(
    (target: ResizeTarget, key: string, shift: boolean): void => {
      const step = shift ? 40 : 16;
      if (target === 'navigator') {
        const value =
          key === 'Home'
            ? 220
            : key === 'End'
              ? 620
              : workspaceState.navigatorWidth + (key === 'ArrowRight' ? step : -step);
        updateWorkspaceState({
          navigatorWidth: clamp(value, 220, 620),
          navigatorCollapsed: key === 'Home'
        });
      } else if (target === 'coordination') {
        const value =
          key === 'Home'
            ? 280
            : key === 'End'
              ? 680
              : workspaceState.coordinationWidth + (key === 'ArrowLeft' ? step : -step);
        updateWorkspaceState({
          coordinationWidth: clamp(value, 280, 680),
          coordinationCollapsed: key === 'Home'
        });
      } else {
        const value =
          key === 'Home'
            ? 120
            : key === 'End'
              ? 480
              : workspaceState.activityHeight + (key === 'ArrowUp' ? step : -step);
        updateWorkspaceState({
          activityHeight: clamp(value, 120, 480),
          activityCollapsed: key === 'Home'
        });
      }
    },
    [updateWorkspaceState, workspaceState]
  );

  const style = {
    '--woven-navigator-width': `${
      workspaceState.navigatorCollapsed ? 56 : workspaceState.navigatorWidth
    }px`,
    '--woven-coordination-width': `${
      workspaceState.coordinationCollapsed ? 56 : workspaceState.coordinationWidth
    }px`,
    '--woven-activity-height': `${
      workspaceState.activityCollapsed ? 68 : workspaceState.activityHeight
    }px`
  } as CSSProperties;
  const replayVisible = replayState.status !== 'IDLE';

  return (
    <ShellFrame
      section="CHAT"
      title="Woven Dialogue"
      subtitle="A shared professional workspace where dialogue produces inspectable artifacts and governed work."
      variant="workspace"
    >
      <section className="woven-workspace" style={style} data-woven-surface="dialogue">
        <main className="woven-dialogue-region" aria-label="Primary Dialogue">
          <DialogueViewport
            primaryDialogue={
              <>
                <div className="woven-dialogue-toolbar">
                  <div>
                    <p className="woven-eyebrow">Primary conversation</p>
                    <h2>Dialogue</h2>
                  </div>
                  <PersonaPicker disabled={streaming} />
                </div>
                <Suspense fallback={<p className="panel-empty">Loading primary dialogue…</p>}>
                  <ChatPanel onActiveSessionChange={setPrimarySessionId} />
                </Suspense>
              </>
            }
          />
        </main>

        <div
          className={
            workspaceState.navigatorCollapsed
              ? 'woven-region woven-region--navigator is-collapsed'
              : 'woven-region woven-region--navigator'
          }
        >
          <button
            type="button"
            className="woven-region-toggle button-muted"
            onClick={() => {
              updateWorkspaceState({
                navigatorCollapsed: !workspaceState.navigatorCollapsed
              });
            }}
          >
            {workspaceState.navigatorCollapsed ? 'Open Navigator' : 'Close Navigator'}
          </button>
          {!workspaceState.navigatorCollapsed ? (
            <Navigator
              activeSurface="dialogue"
              legacyHref={legacyHref}
              sessions={sessions}
              sessionSurfaces={workspaceState.sessionSurfaces}
              liveSessionId={primarySessionId}
              selectedSessionId={selectedReplayId(replayState)}
              selectionDisabled={streaming}
              sessionsLoading={sessionsLoading}
              sessionsError={sessionsError}
              onOpenSurface={returnToPrimaryDialogue}
              onSelectSession={loadReplay}
            />
          ) : (
            <span className="woven-collapsed-label">Navigator</span>
          )}
        </div>

        <div
          className="woven-resize-handle woven-resize-handle--vertical woven-resize-handle--navigator"
          role="separator"
          tabIndex={0}
          aria-label="Resize Navigator"
          aria-orientation="vertical"
          aria-valuemin={220}
          aria-valuemax={620}
          aria-valuenow={workspaceState.navigatorWidth}
          onPointerDown={(event) => {
            beginResize(event, 'navigator');
          }}
          onKeyDown={(event) => {
            if (
              ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)
            ) {
              event.preventDefault();
              resizeByKeyboard('navigator', event.key, event.shiftKey);
            }
          }}
        />

        <div
          className="woven-resize-handle woven-resize-handle--vertical woven-resize-handle--coordination"
          role="separator"
          tabIndex={0}
          aria-label="Resize Coordination Panel"
          aria-orientation="vertical"
          aria-valuemin={280}
          aria-valuemax={680}
          aria-valuenow={workspaceState.coordinationWidth}
          onPointerDown={(event) => {
            beginResize(event, 'coordination');
          }}
          onKeyDown={(event) => {
            if (
              ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)
            ) {
              event.preventDefault();
              resizeByKeyboard('coordination', event.key, event.shiftKey);
            }
          }}
        />

        <aside
          className={
            workspaceState.coordinationCollapsed
              ? 'woven-region woven-region--coordination is-collapsed'
              : 'woven-region woven-region--coordination'
          }
        >
          <button
            type="button"
            className="woven-region-toggle button-muted"
            onClick={() => {
              updateWorkspaceState({
                coordinationCollapsed: !workspaceState.coordinationCollapsed
              });
            }}
          >
            {workspaceState.coordinationCollapsed ? 'Open Coordination' : 'Close Coordination'}
          </button>
          {!workspaceState.coordinationCollapsed ? (
            <CoordinationPanel
              activeView={coordinationView}
              replaySlot={
                replayVisible ? (
                  <SelectedSessionReplayLens
                    state={replayState}
                    primarySessionId={primarySessionId}
                    onReturnToPrimary={returnToPrimaryDialogue}
                    onRetry={() => {
                      const sessionId = selectedReplayId(replayState);
                      if (sessionId) {
                        void replayLoaderRef.current?.load(sessionId, {
                          observedAt: new Date().toISOString(),
                          availableSessionIds: new Set(sessions.map((session) => session.sessionId))
                        });
                      }
                    }}
                  />
                ) : undefined
              }
              hierarchy={hierarchy}
              sessionsLoading={sessionsLoading}
              sessionsError={sessionsError}
              selectedSessionId={selectedReplayId(replayState)}
              selectionDisabled={streaming}
              onSelectView={(coordinationView) => {
                setCoordinationView(coordinationView);
              }}
              onRefreshSessions={() => {
                setSessionRefreshToken((token) => token + 1);
              }}
              onSelectSession={loadReplay}
            />
          ) : (
            <span className="woven-collapsed-label">Coordination</span>
          )}
        </aside>

        <div
          className="woven-resize-handle woven-resize-handle--horizontal"
          role="separator"
          tabIndex={0}
          aria-label="Resize Activity Shelf"
          aria-orientation="horizontal"
          aria-valuemin={120}
          aria-valuemax={480}
          aria-valuenow={workspaceState.activityHeight}
          onPointerDown={(event) => {
            beginResize(event, 'activity');
          }}
          onKeyDown={(event) => {
            if (['ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) {
              event.preventDefault();
              resizeByKeyboard('activity', event.key, event.shiftKey);
            }
          }}
        />

        <ActivityShelf
          collapsed={workspaceState.activityCollapsed}
          onToggleCollapsed={() => {
            updateWorkspaceState({
              activityCollapsed: !workspaceState.activityCollapsed
            });
          }}
        />
      </section>
    </ShellFrame>
  );
}
